INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7280030, 1134851, 96574, '<td valign="top">SWEET! Really nice job on this one.</td>', 'SWEET! Really nice job on this one.', '2014-11-05 00:45:41.000000', NULL, 1),
(7280034, 1133736, 30982, '<td valign="top">Something from the pages of a book, long ago.  Lovely!!</td>', 'Something from the pages of a book, long ago.  Lovely!!', '2014-11-05 00:58:31.000000', NULL, 1),
(7280036, 1134920, 30982, '<td valign="top">What a view she has from her throne!  Her subjects appear curious, but loyal.</td>', 'What a view she has from her throne!  Her subjects appear curious, but loyal.', '2014-11-05 00:59:03.000000', NULL, 1),
(7280037, 1134928, 30982, '<td valign="top">The human element, rapidly being replaced by screen replications.</td>', 'The human element, rapidly being replaced by screen replications.', '2014-11-05 00:59:37.000000', NULL, 1),
(7280038, 1133164, 30982, '<td valign="top">This is a wonderful photograph.  Thank you for sharing it.  Such warmth, and such an endeavor!  That''s a lot of peeling.</td>', 'This is a wonderful photograph.  Thank you for sharing it.  Such warmth, and such an endeavor!  That''s a lot of peeling.', '2014-11-05 01:00:33.000000', NULL, 1),
(7280039, 1134897, 30982, '<td valign="top">Nice contrasts in the warmth of the flame, the cool blue of the smoke.</td>', 'Nice contrasts in the warmth of the flame, the cool blue of the smoke.', '2014-11-05 01:00:56.000000', NULL, 1),
(7280040, 1134506, 30982, '<td valign="top">Very stark and lonely.  Great contrast.  I like the unsettled nature of the slight tilt - it adds a sense of unease.</td>', 'Very stark and lonely.  Great contrast.  I like the unsettled nature of the slight tilt - it adds a sense of unease.', '2014-11-05 01:01:44.000000', NULL, 1),
(7280041, 1133254, 30982, '<td valign="top">Something compelling about such a snapshot kinda picture - could be the face of the driver that you don''t see right away because the headlight takes your attention....</td>', 'Something compelling about such a snapshot kinda picture - could be the face of the driver that you don''t see right away because the headlight takes your attention....', '2014-11-05 01:04:17.000000', NULL, 1),
(7280042, 1133746, 30982, '<td valign="top">Mostly I get the sense of isolation, both because of the fence and the distance to what we can see of civilization.  Very stark.</td>', 'Mostly I get the sense of isolation, both because of the fence and the distance to what we can see of civilization.  Very stark.', '2014-11-05 01:05:35.000000', NULL, 1),
(7280043, 1133216, 30982, '<td valign="top">Ah, I''ve seen this beautiful view before - great color and clarity.</td>', 'Ah, I''ve seen this beautiful view before - great color and clarity.', '2014-11-05 01:06:18.000000', NULL, 1),
(7280044, 1134724, 30982, '<td valign="top">Gentle and sweet.</td>', 'Gentle and sweet.', '2014-11-05 01:06:31.000000', NULL, 1),
(7280046, 1133924, 30982, '<td valign="top">College life?  The guy just over his shoulder is haunting; the girl looks disappointed.  Our Lizard King is oblivious to all behind him, and our intrepid photographer is seeking an angle.  He missed; you got it.</td>', 'College life?  The guy just over his shoulder is haunting; the girl looks disappointed.  Our Lizard King is oblivious to all behind him, and our intrepid photographer is seeking an angle.  He missed; you got it.', '2014-11-05 01:08:04.000000', NULL, 1),
(7280047, 1133469, 30982, '<td valign="top">A very fun shot to explore!</td>', 'A very fun shot to explore!', '2014-11-05 01:09:11.000000', NULL, 1),
(7280048, 1133940, 30982, '<td valign="top">Before I even saw your title, I thought "Tango".  Well captured.</td>', 'Before I even saw your title, I thought "Tango".  Well captured.', '2014-11-05 01:09:38.000000', NULL, 1),
(7280050, 1134710, 30982, '<td valign="top">I like your image.  There''s a sense of foreboding in a way.  But I really wish you''d have taken the time to provide a title, even if it were "Untitled".</td>', 'I like your image.  There''s a sense of foreboding in a way.  But I really wish you''d have taken the time to provide a title, even if it were "Untitled".', '2014-11-05 01:10:42.000000', NULL, 1),
(7280051, 1133739, 30982, '<td valign="top">She''s turning into a gorgeous young lady!  I''ve enjoyed watching her grow and am glad to see she''s well past the stage where she didn''t want you to take her picture.  A very sweet shot - nice work on your part as the photographer, and her part as the model!</td>', 'She''s turning into a gorgeous young lady!  I''ve enjoyed watching her grow and am glad to see she''s well past the stage where she didn''t want you to take her picture.  A very sweet shot - nice work on your part as the photographer, and her part as the model!', '2014-11-05 01:11:39.000000', NULL, 1),
(7280052, 1134808, 30982, '<td valign="top">Quite serene!</td>', 'Quite serene!', '2014-11-05 01:11:49.000000', NULL, 1),
(7280058, 1133275, 40391, '<td valign="top">Wonderful details and great capture.</td>', 'Wonderful details and great capture.', '2014-11-05 02:07:12.000000', NULL, 1),
(7280059, 1134662, 40391, '<td valign="top">Love it!</td>', 'Love it!', '2014-11-05 02:08:40.000000', NULL, 1),
(7280060, 1134397, 20056, '<td valign="top">225 (15x15) :)</td>', '225 (15x15) :)', '2014-11-05 02:15:01.000000', NULL, 1),
(7280062, 1134487, 141826, '<td valign="top">WOW!!!!!! 10++</td>', 'WOW!!!!!! 10++', '2014-11-05 02:56:20.000000', NULL, 1),
(7280063, 1134529, 114285, '<td valign="top">Double whammy, this is the best I''ve ever seen Sydney at, and I don''t normally like cityscapes but this is marvellously done!</td>', 'Double whammy, this is the best I''ve ever seen Sydney at, and I don''t normally like cityscapes but this is marvellously done!', '2014-11-05 02:57:57.000000', NULL, 1),
(7280065, 1134608, 141826, '<td valign="top">10++</td>', '10++', '2014-11-05 03:05:39.000000', NULL, 1),
(7280073, 1133199, 159723, '<td valign="top">Love it!</td>', 'Love it!', '2014-11-05 05:37:39.000000', NULL, 1),
(7280074, 1134645, 159723, '<td valign="top">Nice colors!</td>', 'Nice colors!', '2014-11-05 05:42:22.000000', NULL, 1),
(7280077, 1133471, 159723, '<td valign="top">The forground has too much saturation for my liking, and the roofs are very grainy. However, the sky is gorgeous!</td>', 'The forground has too much saturation for my liking, and the roofs are very grainy. However, the sky is gorgeous!', '2014-11-05 05:52:19.000000', NULL, 1),
(7280078, 1134718, 81362, '<td valign="top">Absolute WOW. Love the very soft, subtly directional light on the trunks. Wonderful enhancement of tiny bits of red down low and close that harmonize with darker shadowed blues further away. Bits of snow/ice establish credible white points while the darkest trunk spots reach to the full other end of the luminosity scale. Aspens can frustrate us with endless potentially wonderful images that turn out to be very difficult to capture in a way that matches artistic intent. You demonstrate technical mastery with an image that evokes a sense of peaceful enjoyment of a quiet bit of natural beauty.</td>', 'Absolute WOW. Love the very soft, subtly directional light on the trunks. Wonderful enhancement of tiny bits of red down low and close that harmonize with darker shadowed blues further away. Bits of snow/ice establish credible white points while the darkest trunk spots reach to the full other end of the luminosity scale. Aspens can frustrate us with endless potentially wonderful images that turn out to be very difficult to capture in a way that matches artistic intent. You demonstrate technical mastery with an image that evokes a sense of peaceful enjoyment of a quiet bit of natural beauty.', '2014-11-05 05:53:25.000000', NULL, 1),
(7280080, 1134742, 81362, '<td valign="top">Excellent choice to retain the subtle dark browns of trunks and branches. That gives a much more natural feel to the setting. The splash of blue snow suit lends energy and liveliness to the image out of proportion to the actual number of pixels involved. Having the curved branch serve as a frame for the person and as a separator between the smoother snow and the intricate canopy of tree branches works well. Takes good advantage of the newly allowed larger image size.</td>', 'Excellent choice to retain the subtle dark browns of trunks and branches. That gives a much more natural feel to the setting. The splash of blue snow suit lends energy and liveliness to the image out of proportion to the actual number of pixels involved. Having the curved branch serve as a frame for the person and as a separator between the smoother snow and the intricate canopy of tree branches works well. Takes good advantage of the newly allowed larger image size.', '2014-11-05 05:59:22.000000', NULL, 1),
(7280081, 1134904, 159723, '<td valign="top">Great shot! Such a beautiful animal! I get a bit distracted by the background. (And is there a purplish light on the legs or is that just my monitor?)</td>', 'Great shot! Such a beautiful animal! I get a bit distracted by the background. (And is there a purplish light on the legs or is that just my monitor?)', '2014-11-05 06:03:50.000000', NULL, 1),
(7280083, 1133962, 81362, '<td valign="top">Excellent image. Well balanced composition (harder to achieve than it looks), snow nicely exposed to look white enough but still show detail, repeating rhythm of fence posts keeping the beat across the fields while the brush and branches support the reddish-brown visual melody. You present us with a classical rural winter scene that is easy to enjoy.</td>', 'Excellent image. Well balanced composition (harder to achieve than it looks), snow nicely exposed to look white enough but still show detail, repeating rhythm of fence posts keeping the beat across the fields while the brush and branches support the reddish-brown visual melody. You present us with a classical rural winter scene that is easy to enjoy.', '2014-11-05 06:07:20.000000', NULL, 1),
(7280084, 1134097, 159723, '<td valign="top">I rarely go all gooey from images containing animals, but this... Oh my, too cute! And a great shot too!</td>', 'I rarely go all gooey from images containing animals, but this... Oh my, too cute! And a great shot too!', '2014-11-05 06:11:58.000000', NULL, 1),
(7280088, 1134501, 159723, '<td valign="top">I like it! I think I would have scored it higher if the area above what I assume is its nostril was more in focus.</td>', 'I like it! I think I would have scored it higher if the area above what I assume is its nostril was more in focus.', '2014-11-05 06:20:44.000000', NULL, 1),
(7280101, 1134537, 159723, '<td valign="top">I think I would have preferred if both foreground and background was equally in focus, but I might be wrong :)</td>', 'I think I would have preferred if both foreground and background was equally in focus, but I might be wrong :)', '2014-11-05 07:07:50.000000', NULL, 1),
