(7280519, 1133706, 81362, '<td valign="top">Bold idea to submit such a stark portrait, but one of my top five in the challenge. Staring expression works well with the hard side light. Wide black area on the right somehow balances the face and smaller black area on the left. Sharp, interesting, and somewhat unusual.</td>', 'Bold idea to submit such a stark portrait, but one of my top five in the challenge. Staring expression works well with the hard side light. Wide black area on the right somehow balances the face and smaller black area on the left. Sharp, interesting, and somewhat unusual.', '2014-11-05 19:12:42.000000', NULL, 1),
(7280523, 1134397, 81362, '<td valign="top">Evokes sense of calm and contemplation. Unusual light captured without excessive digital noise. Deserves to do well.</td>', 'Evokes sense of calm and contemplation. Unusual light captured without excessive digital noise. Deserves to do well.', '2014-11-05 19:14:16.000000', NULL, 1),
(7280531, 1134622, 81362, '<td valign="top">Thanks for the laugh. Black and white keeps us focused on the essential elements of the image. Excellent idea to have such a uniquely dressed person selected to have the cartoon balloon "statement."</td>', 'Thanks for the laugh. Black and white keeps us focused on the essential elements of the image. Excellent idea to have such a uniquely dressed person selected to have the cartoon balloon "statement."', '2014-11-05 19:16:24.000000', NULL, 1),
(7280540, 1133936, 81362, '<td valign="top">Composition does have some separation into foreground, mid-ground, and background, but it is difficult to land on a particular subject of interest. The palms and vegetation could be interesting if showing more detail (maybe move closer and apply some sharpening in post processing). Mostly it seems a shame to enter such a small version in the first challenge to allow 1200 pixel sides. That will probably decrease the overall score.</td>', 'Composition does have some separation into foreground, mid-ground, and background, but it is difficult to land on a particular subject of interest. The palms and vegetation could be interesting if showing more detail (maybe move closer and apply some sharpening in post processing). Mostly it seems a shame to enter such a small version in the first challenge to allow 1200 pixel sides. That will probably decrease the overall score.', '2014-11-05 19:26:57.000000', NULL, 1),
(7280541, 1133409, 81362, '<td valign="top">Dark bird on bright yellow highly textured field evokes some feelings generated by the Van Gough painting Wheatfield with Crows. Unfortunately, a photograph might have to wait a long time to reach similar pricing. Enjoyable image that should do well.</td>', 'Dark bird on bright yellow highly textured field evokes some feelings generated by the Van Gough painting Wheatfield with Crows. Unfortunately, a photograph might have to wait a long time to reach similar pricing. Enjoyable image that should do well.', '2014-11-05 19:31:16.000000', NULL, 1),
(7280544, 1133180, 81362, '<td valign="top">Left brain wants to dislike this, but right brain takes over and likes it anyway. That makes literate commentary challenging, but the image does a good job of communicating subtleties of urban essence visually instead of with words.</td>', 'Left brain wants to dislike this, but right brain takes over and likes it anyway. That makes literate commentary challenging, but the image does a good job of communicating subtleties of urban essence visually instead of with words.', '2014-11-05 19:37:30.000000', NULL, 1),
(7280546, 1134875, 81362, '<td valign="top">Impressive use of light, color, and compositional excellence. Bumping up to eight now that I''ve seen all the entries and had time to look again.</td>', 'Impressive use of light, color, and compositional excellence. Bumping up to eight now that I''ve seen all the entries and had time to look again.', '2014-11-05 19:38:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7280548, 1134097, 114285, '<td valign="top">Extremely cute indeed, seems the fan is blowing up and over her though, but I could be wrong. 7</td>', 'Extremely cute indeed, seems the fan is blowing up and over her though, but I could be wrong. 7', '2014-11-05 19:39:18.000000', NULL, 1),
(7280550, 1134766, 114285, '<td valign="top">Wonderful, wish you had of titled it though.</td>', 'Wonderful, wish you had of titled it though.', '2014-11-05 19:40:39.000000', NULL, 1),
(7280551, 1133889, 114285, '<td valign="top">I love how his mouth mimics his body, awesome stuff!</td>', 'I love how his mouth mimics his body, awesome stuff!', '2014-11-05 19:41:41.000000', NULL, 1),
(7280553, 1134662, 81362, '<td valign="top">What a marvelous combination of lighting, expression, humor and color. Good image to pull out for students who need to learn that simple backgrounds can still be interesting, and that color relationships can be introduced without hitting the viewer over the head with them. Predicting a high score.</td>', 'What a marvelous combination of lighting, expression, humor and color. Good image to pull out for students who need to learn that simple backgrounds can still be interesting, and that color relationships can be introduced without hitting the viewer over the head with them. Predicting a high score.', '2014-11-05 19:42:49.000000', NULL, 1),
(7280554, 1133675, 81362, '<td valign="top">Green apple against red background provides an opportunity for a strong image. However, because our eyes automatically give extra attention to high contrast areas, the bright white background contrasting with red leaves diminishes our appreciation of the main subject. Similar issue with the fingertips. A bit of repositioning might help avoid these issues.</td>', 'Green apple against red background provides an opportunity for a strong image. However, because our eyes automatically give extra attention to high contrast areas, the bright white background contrasting with red leaves diminishes our appreciation of the main subject. Similar issue with the fingertips. A bit of repositioning might help avoid these issues.', '2014-11-05 19:47:49.000000', NULL, 1),
(7280559, 1133156, 30982, '<td valign="top">Sweet scene, and what wonderful light!</td>', 'Sweet scene, and what wonderful light!', '2014-11-05 19:56:32.000000', NULL, 1),
(7280561, 1134840, 30982, '<td valign="top">I like your choice of toning for this.</td>', 'I like your choice of toning for this.', '2014-11-05 19:57:17.000000', NULL, 1),
(7280562, 1134819, 30982, '<td valign="top">Very bright and colorful!</td>', 'Very bright and colorful!', '2014-11-05 19:57:51.000000', NULL, 1),
(7280563, 1134637, 30982, '<td valign="top">What a graceful pose!  Seems as though it may have been cropped a fair amount because the feathers seem to be lacking a bit of detail, the overall impact of the photograph is good.</td>', 'What a graceful pose!  Seems as though it may have been cropped a fair amount because the feathers seem to be lacking a bit of detail, the overall impact of the photograph is good.', '2014-11-05 19:59:12.000000', NULL, 1),
(7280565, 1133817, 30982, '<td valign="top">A nice postcard view - lovely colors in the foreground tree.</td>', 'A nice postcard view - lovely colors in the foreground tree.', '2014-11-05 19:59:28.000000', NULL, 1),
(7280566, 1134843, 30982, '<td valign="top">I like your choice of the widescreen view - gives a sense of expansiveness.</td>', 'I like your choice of the widescreen view - gives a sense of expansiveness.', '2014-11-05 19:59:56.000000', NULL, 1),
(7280568, 1133765, 30982, '<td valign="top">Pretty bird, captured very well.  I especially like the golden glow of the bokeh behind.</td>', 'Pretty bird, captured very well.  I especially like the golden glow of the bokeh behind.', '2014-11-05 20:00:17.000000', NULL, 1),
(7280569, 1134321, 30982, '<td valign="top">A lot of work, to get them all in.  Seems a dream in stutterstep.</td>', 'A lot of work, to get them all in.  Seems a dream in stutterstep.', '2014-11-05 20:00:41.000000', NULL, 1),
(7280571, 1134454, 30982, '<td valign="top">A nice abstractish kinda thing.</td>', 'A nice abstractish kinda thing.', '2014-11-05 20:01:06.000000', NULL, 1),
