(7280574, 1134332, 30982, '<td valign="top">Peaceful, but cold!  I think the trees stay that close together just for warmth in the winter.</td>', 'Peaceful, but cold!  I think the trees stay that close together just for warmth in the winter.', '2014-11-05 20:02:31.000000', NULL, 1),
(7280576, 1134525, 30982, '<td valign="top">Love the reflection in that window.  Nice textures.</td>', 'Love the reflection in that window.  Nice textures.', '2014-11-05 20:03:29.000000', NULL, 1),
(7280577, 1134112, 30982, '<td valign="top">Ever so delicate and quiet in the gray - would make a great card.</td>', 'Ever so delicate and quiet in the gray - would make a great card.', '2014-11-05 20:04:28.000000', NULL, 1),
(7280579, 1134238, 30982, '<td valign="top">A lovely rural scene - the glow suits here.</td>', 'A lovely rural scene - the glow suits here.', '2014-11-05 20:05:01.000000', NULL, 1),
(7280580, 1134906, 30982, '<td valign="top">Holy cow, that''s some sky!</td>', 'Holy cow, that''s some sky!', '2014-11-05 20:05:17.000000', NULL, 1),
(7280582, 1133926, 30982, '<td valign="top">Nice supporting cast with the sky and setting sun.</td>', 'Nice supporting cast with the sky and setting sun.', '2014-11-05 20:05:33.000000', NULL, 1),
