INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7281132, 1134648, 101668, '<td valign="top">The orphans of the world. Nice shot</td>', 'The orphans of the world. Nice shot', '2014-11-06 16:50:11.000000', NULL, 1),
(7281133, 1133156, 101668, '<td valign="top">Massive horns and great light</td>', 'Massive horns and great light', '2014-11-06 16:51:44.000000', NULL, 1),
(7281134, 1134506, 101668, '<td valign="top">not crazy about the tilt, but interesting enough. Good shot</td>', 'not crazy about the tilt, but interesting enough. Good shot', '2014-11-06 16:52:35.000000', NULL, 1),
(7281135, 1134940, 101668, '<td valign="top">on stormy seas. Nice one</td>', 'on stormy seas. Nice one', '2014-11-06 16:53:23.000000', NULL, 1),
(7281136, 1134608, 101668, '<td valign="top">So difficult to photograph one, let alone two, fantastic sharp and crisp</td>', 'So difficult to photograph one, let alone two, fantastic sharp and crisp', '2014-11-06 16:54:14.000000', NULL, 1),
