(7282450, 1133927, 13077, '<td valign="top">Good composition, nice hard light and the smoky atmosphere is great. Very cool environmental portrait.</td>', 'Good composition, nice hard light and the smoky atmosphere is great. Very cool environmental portrait.', '2014-11-08 19:31:03.000000', NULL, 1),
