(7282453, 1134742, 13077, '<td valign="top">walkin'' in a winter wonderland...</td>', 'walkin'' in a winter wonderland...', '2014-11-08 19:32:24.000000', NULL, 1),
(7282454, 1134697, 13077, '<td valign="top">Beautiful scene, very wild. Great sky too, and the crop looks perfect.</td>', 'Beautiful scene, very wild. Great sky too, and the crop looks perfect.', '2014-11-08 19:33:00.000000', NULL, 1),
(7282455, 1133924, 13077, '<td valign="top">LOL - crazy photo, so much going on. Captures a wild party atmosphere well.</td>', 'LOL - crazy photo, so much going on. Captures a wild party atmosphere well.', '2014-11-08 19:33:29.000000', NULL, 1),
(7282456, 1134908, 13077, '<td valign="top">Very nice light, and excellent detail in the moist surfaces and different textures and shapes.</td>', 'Very nice light, and excellent detail in the moist surfaces and different textures and shapes.', '2014-11-08 19:34:13.000000', NULL, 1),
