(7282465, 1133814, 13077, '<td valign="top">Interesting - I like the inclusion of the stars here.</td>', 'Interesting - I like the inclusion of the stars here.', '2014-11-08 19:39:05.000000', NULL, 1),
(7282467, 1134416, 13077, '<td valign="top">Is that austin powers? lol</td>', 'Is that austin powers? lol', '2014-11-08 19:39:28.000000', NULL, 1),
(7282468, 1133750, 13077, '<td valign="top">Interesting glowing haze in the sky.</td>', 'Interesting glowing haze in the sky.', '2014-11-08 19:40:12.000000', NULL, 1),
(7282469, 1134722, 13077, '<td valign="top">It does look like a nice place, but the photo looks a bit over-sharpened and some detail seems to have been lost.</td>', 'It does look like a nice place, but the photo looks a bit over-sharpened and some detail seems to have been lost.', '2014-11-08 19:40:43.000000', NULL, 1),
(7282470, 1134450, 13077, '<td valign="top">Very cool architecture, and nicely composed.I probably would have done some color-shifting of the parts that aren''t brightly illuminated, but that''s just me.</td>', 'Very cool architecture, and nicely composed.I probably would have done some color-shifting of the parts that aren''t brightly illuminated, but that''s just me.', '2014-11-08 19:41:48.000000', NULL, 1),
(7282471, 1134900, 13077, '<td valign="top">Beautiful lake. Could be an advertisement for fishing equipment.</td>', 'Beautiful lake. Could be an advertisement for fishing equipment.', '2014-11-08 19:42:17.000000', NULL, 1),
(7282472, 1134843, 13077, '<td valign="top">Oregon maybe?<br/>I like this - nicely composed and good exposure, and the clouds are really interesting.</td>', 'Oregon maybe?I like this - nicely composed and good exposure, and the clouds are really interesting.', '2014-11-08 19:42:57.000000', NULL, 1),
(7282473, 1134870, 13077, '<td valign="top">Nice - clean, well exposed and sharp, and good composition.</td>', 'Nice - clean, well exposed and sharp, and good composition.', '2014-11-08 19:43:31.000000', NULL, 1),
(7282474, 1134829, 13077, '<td valign="top">Excellent!</td>', 'Excellent!', '2014-11-08 19:43:43.000000', NULL, 1),
(7282476, 1133469, 13077, '<td valign="top">Fascinating, beautiful scene, perfectly timed and excellent post processing. I love it.</td>', 'Fascinating, beautiful scene, perfectly timed and excellent post processing. I love it.', '2014-11-08 19:44:42.000000', NULL, 1),
(7282477, 1134764, 13077, '<td valign="top">Yum! Very good wildlife shot - perfect exposure, sharp focus, tells a story, clean background, well composed.</td>', 'Yum! Very good wildlife shot - perfect exposure, sharp focus, tells a story, clean background, well composed.', '2014-11-08 19:45:24.000000', NULL, 1),
(7282478, 1134439, 13077, '<td valign="top">Nice car, and I like the light and the detail in the pavement.</td>', 'Nice car, and I like the light and the detail in the pavement.', '2014-11-08 19:45:46.000000', NULL, 1),
(7282479, 1134909, 13077, '<td valign="top">Nice capture - good slice of motoring life in (I''m assuming) the middle east.</td>', 'Nice capture - good slice of motoring life in (I''m assuming) the middle east.', '2014-11-08 19:46:27.000000', NULL, 1),
(7282480, 1134861, 13077, '<td valign="top">Super cool building - nicely composed and I like the B&amp;W treatment and the clouds behind it.</td>', 'Super cool building - nicely composed and I like the B&W treatment and the clouds behind it.', '2014-11-08 19:46:50.000000', NULL, 1),
(7282482, 1134678, 13077, '<td valign="top">I was there once, but without a digital camera - didn''t have this wide of a lens so I shot from maybe 100 feet to the right of where you were. This is a nicer view, and the light looks good. A more dramatic sky probably would have helped, but oh well.</td>', 'I was there once, but without a digital camera - didn''t have this wide of a lens so I shot from maybe 100 feet to the right of where you were. This is a nicer view, and the light looks good. A more dramatic sky probably would have helped, but oh well.', '2014-11-08 19:48:51.000000', NULL, 1),
(7282483, 1133388, 13077, '<td valign="top">Nice composition and excellent detail from the foreground to infinity. Very cool light and nice clouds too.</td>', 'Nice composition and excellent detail from the foreground to infinity. Very cool light and nice clouds too.', '2014-11-08 19:49:35.000000', NULL, 1),
(7282484, 1134098, 13077, '<td valign="top">Awww. Excellent composition and good sharp detail, nice looking colors too.</td>', 'Awww. Excellent composition and good sharp detail, nice looking colors too.', '2014-11-08 19:49:56.000000', NULL, 1),
(7282485, 1133365, 13077, '<td valign="top">I like the haze and the sort of dreamlike feel to this. The trees in silhouette add just enough realism to it.</td>', 'I like the haze and the sort of dreamlike feel to this. The trees in silhouette add just enough realism to it.', '2014-11-08 19:50:26.000000', NULL, 1),
(7282501, 1133527, 60495, '<td valign="top">I love the simplicity of this shot, only nitpick would be the unloved horizon which is an easy fix that would make a big difference.</td>', 'I love the simplicity of this shot, only nitpick would be the unloved horizon which is an easy fix that would make a big difference.', '2014-11-08 21:44:46.000000', NULL, 1),
