(7282786, 1134872, 30364, '<td valign="top">I don''t know what to say.  It''s beautiful, like a fabulously loose drawing.  I looked up the meaning of the title, and it made me feel even better though I''m not certain why.  But uncertainty is one of my favourite things in art, so it''s getting better all the time.  Thank you.</td>', 'I don''t know what to say.  It''s beautiful, like a fabulously loose drawing.  I looked up the meaning of the title, and it made me feel even better though I''m not certain why.  But uncertainty is one of my favourite things in art, so it''s getting better all the time.  Thank you.', '2014-11-09 13:31:34.000000', NULL, 1),
(7282789, 1134840, 30364, '<td valign="top">Landscapes are normally pretty boring, but not this one.  It''s beautifully seen, composed and presented.  8.  Thank you.</td>', 'Landscapes are normally pretty boring, but not this one.  It''s beautifully seen, composed and presented.  8.  Thank you.', '2014-11-09 13:55:29.000000', NULL, 1),
(7282791, 1134698, 30364, '<td valign="top">Whoa!  I love irreconcilable photographs, especially when they are (a) beautiful, and (b) on extended consideration waver in and out of my comprehension.  This one gets ticks in both those boxes from me. 8 &amp; thank you.</td>', 'Whoa!  I love irreconcilable photographs, especially when they are (a) beautiful, and (b) on extended consideration waver in and out of my comprehension.  This one gets ticks in both those boxes from me. 8 & thank you.', '2014-11-09 13:59:13.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7282794, 1134528, 30364, '<td valign="top">Yes.  Just enough stuff to be something, not enough stuff to be easily ticked and flicked.  The viewer, assuming a minimum level of curiosity, can''t avoid giving this a good long run for its money.  Me, I love it.  8 and thank you.</td>', 'Yes.  Just enough stuff to be something, not enough stuff to be easily ticked and flicked.  The viewer, assuming a minimum level of curiosity, can''t avoid giving this a good long run for its money.  Me, I love it.  8 and thank you.', '2014-11-09 14:03:39.000000', NULL, 1),
(7282795, 1134238, 159723, '<td valign="top">I would have liked to see more blue in the sky as it is very similar in color to the roof. I like the composition!</td>', 'I would have liked to see more blue in the sky as it is very similar in color to the roof. I like the composition!', '2014-11-09 14:07:22.000000', NULL, 1),
(7282796, 1134766, 30364, '<td valign="top">Low fidelity photographs are either awful or fabulous.  Yours is fabulous.  It looks so alien, or surreal (one of those, possibly both) and yet it''s no doubt something pretty ordinary in reality.  But reality usually sucks and your transformative influence makes it instead into something uncommon and fascinating.  8 &amp; thank you.</td>', 'Low fidelity photographs are either awful or fabulous.  Yours is fabulous.  It looks so alien, or surreal (one of those, possibly both) and yet it''s no doubt something pretty ordinary in reality.  But reality usually sucks and your transformative influence makes it instead into something uncommon and fascinating.  8 & thank you.', '2014-11-09 14:08:10.000000', NULL, 1),
(7282799, 1133184, 159723, '<td valign="top">Voted earlier, back to comment. I like the b&amp;w conversion and nice colour on the backpack. The image is for me unfortunately not quite as interesting as your competition in this challenge.</td>', 'Voted earlier, back to comment. I like the b&w conversion and nice colour on the backpack. The image is for me unfortunately not quite as interesting as your competition in this challenge.', '2014-11-09 14:10:34.000000', NULL, 1),
(7282800, 1134919, 30364, '<td valign="top">Brilliant.  It''s the photograph as transformative public art.  I''ve got it ... you''re Banksy!  Nice stuff, Banksy, have an 8 and a thank you.</td>', 'Brilliant.  It''s the photograph as transformative public art.  I''ve got it ... you''re Banksy!  Nice stuff, Banksy, have an 8 and a thank you.', '2014-11-09 14:11:39.000000', NULL, 1),
(7282801, 1134910, 159723, '<td valign="top">I would have liked to see at least either the dog or the boy in focus. Looks like their having fun though :)</td>', 'I would have liked to see at least either the dog or the boy in focus. Looks like their having fun though :)', '2014-11-09 14:12:36.000000', NULL, 1),
(7282802, 1134796, 30364, '<td valign="top">Nothing special except for everything you did.  That''s ALL special; vision, technique and processing restraint.  A quietly wonderful photograph, perfectly executed.  8.  Thank you.</td>', 'Nothing special except for everything you did.  That''s ALL special; vision, technique and processing restraint.  A quietly wonderful photograph, perfectly executed.  8.  Thank you.', '2014-11-09 14:13:21.000000', NULL, 1),
(7282803, 1134936, 30364, '<td valign="top">I dunno.  What <i>about</i> us?  Are we screwed yet?  We are if you ever stop doing this.  8 &amp; thank you.</td>', 'I dunno.  What about us?  Are we screwed yet?  We are if you ever stop doing this.  8 & thank you.', '2014-11-09 14:14:21.000000', NULL, 1),
(7282804, 1134720, 76335, '<td valign="top">Liking the grain, the hands, the warmth, the moment...</td>', 'Liking the grain, the hands, the warmth, the moment...', '2014-11-09 14:18:05.000000', NULL, 1),
(7282805, 1134766, 76335, '<td valign="top">How fragile we are...</td>', 'How fragile we are...', '2014-11-09 14:19:46.000000', NULL, 1),
(7282806, 1133177, 30364, '<td valign="top">A terrific example of how the awful can become the wonderful.  I love this, in spite of all popular sentiment against it (which I am anticipating only, at this stage).  It''s mesmerisingly beautiful.  It rewards another look, and another.  It reminds me of something else improbably beautiful but I can''t remember what it was. I don''t even care if YOU think it''s awful  and you might I suppose  I love it.  8 &amp; thank you.</td>', 'A terrific example of how the awful can become the wonderful.  I love this, in spite of all popular sentiment against it (which I am anticipating only, at this stage).  It''s mesmerisingly beautiful.  It rewards another look, and another.  It reminds me of something else improbably beautiful but I can''t remember what it was. I don''t even care if YOU think it''s awful  and you might I suppose  I love it.  8 & thank you.', '2014-11-09 14:20:04.000000', NULL, 1),
