(7283217, 1133806, 13077, '<td valign="top">Must have been a little while back, not a NV200 van in sight.</td>', 'Must have been a little while back, not a NV200 van in sight.', '2014-11-10 12:12:36.000000', NULL, 1),
(7283219, 1133528, 13077, '<td valign="top">I like the inclusion of the other bird in the background. The photo is reasonably sharp - maybe a little motion blur or slightly off focus, but it can be tough to catch birds in flight. I would probably have increased the contrast a bit though, or maybe done some curves and selective coloring to reduce the cyan cast in the shadowed parts of the bird, and to saturate the sky a bit more.</td>', 'I like the inclusion of the other bird in the background. The photo is reasonably sharp - maybe a little motion blur or slightly off focus, but it can be tough to catch birds in flight. I would probably have increased the contrast a bit though, or maybe done some curves and selective coloring to reduce the cyan cast in the shadowed parts of the bird, and to saturate the sky a bit more.', '2014-11-10 12:14:36.000000', NULL, 1),
(7283221, 1134807, 13077, '<td valign="top">It''s an interesting creature, but I don''t find the photo very visually interesting. Maybe it''s the composition, I get the feeling a more attractive composition could have been had with this scene.</td>', 'It''s an interesting creature, but I don''t find the photo very visually interesting. Maybe it''s the composition, I get the feeling a more attractive composition could have been had with this scene.', '2014-11-10 12:15:51.000000', NULL, 1),
(7283222, 1133364, 170281, '<td valign="top">Color difference is cool, but I think there would be greater impact if the eyes were in focus.</td>', 'Color difference is cool, but I think there would be greater impact if the eyes were in focus.', '2014-11-10 12:16:02.000000', NULL, 1),
(7283223, 1134923, 13077, '<td valign="top">At least her clothes won''t get wet! lol<br/>Nicely composed and good shutter speed for the water, also kudos to the model for holding still for that amount of time.</td>', 'At least her clothes won''t get wet! lolNicely composed and good shutter speed for the water, also kudos to the model for holding still for that amount of time.', '2014-11-10 12:17:03.000000', NULL, 1),
