(7283226, 1133446, 13077, '<td valign="top">Very ''cool''!<br/>Nicely composed and exposed, and the wispy clouds complement the scene well.</td>', 'Very ''cool''!Nicely composed and exposed, and the wispy clouds complement the scene well.', '2014-11-10 12:23:31.000000', NULL, 1),
