(7283390, 1133275, 25024, '<td valign="top">A great image, I love the high key effect though the somewhat unnatural background does make it feel unreal, nevertheless, a high score.</td>', 'A great image, I love the high key effect though the somewhat unnatural background does make it feel unreal, nevertheless, a high score.', '2014-11-10 17:29:49.000000', NULL, 1),
(7283391, 1134662, 25024, '<td valign="top">A gorgeous image, I love everything about it., the relaxed pose, the vivid green background, the colours, the shadows, the goat on the right, it all works so well, a high score.</td>', 'A gorgeous image, I love everything about it., the relaxed pose, the vivid green background, the colours, the shadows, the goat on the right, it all works so well, a high score.', '2014-11-10 17:32:30.000000', NULL, 1),
(7283392, 1134397, 25024, '<td valign="top">I love the lighting and blackness, it works for me, a high score.</td>', 'I love the lighting and blackness, it works for me, a high score.', '2014-11-10 17:33:30.000000', NULL, 1),
(7283393, 1133250, 47974, '<td valign="top">Wonderful capture, does look far far way......can''t wait to see how it was done.  Only negative comment is I personally do not like borders.</td>', 'Wonderful capture, does look far far way......can''t wait to see how it was done.  Only negative comment is I personally do not like borders.', '2014-11-10 17:34:22.000000', NULL, 1),
(7283394, 1134321, 47974, '<td valign="top">As a photograph I think this is terrible.........as a work of art I am in love with it.  Wonderful and amazing processing, can''t wait to find out how you did it.  A 7 for now, I have a strange way of scoring and this will either go up or stay a 7 on my 2nd pass.</td>', 'As a photograph I think this is terrible.........as a work of art I am in love with it.  Wonderful and amazing processing, can''t wait to find out how you did it.  A 7 for now, I have a strange way of scoring and this will either go up or stay a 7 on my 2nd pass.', '2014-11-10 17:34:49.000000', NULL, 1),
(7283395, 1133823, 25024, '<td valign="top">You have really conveyed the cold and bleakness well, who''d be a poor cold pony? Lovely mono conversion, works well, a high score</td>', 'You have really conveyed the cold and bleakness well, who''d be a poor cold pony? Lovely mono conversion, works well, a high score', '2014-11-10 17:36:08.000000', NULL, 1),
(7283396, 1133158, 47974, '<td valign="top">Beautiful and inspiring photograph.  It''s such a wonderful capture that I don''t mind the horizon being at the center line (something that normally bothers me).  Really love how the sun is just behind the island.  Great image...........</td>', 'Beautiful and inspiring photograph.  It''s such a wonderful capture that I don''t mind the horizon being at the center line (something that normally bothers me).  Really love how the sun is just behind the island.  Great image...........', '2014-11-10 17:36:47.000000', NULL, 1),
(7283397, 1134608, 47974, '<td valign="top">Absolutely stunning</td>', 'Absolutely stunning', '2014-11-10 17:37:51.000000', NULL, 1),
(7283398, 1134098, 47974, '<td valign="top">beautifully executed</td>', 'beautifully executed', '2014-11-10 17:38:29.000000', NULL, 1),
(7283399, 1133409, 25024, '<td valign="top">Gorgeous! Great composition, great colours, great light, great focus and DOF, great score!</td>', 'Gorgeous! Great composition, great colours, great light, great focus and DOF, great score!', '2014-11-10 17:38:56.000000', NULL, 1),
(7283400, 1133765, 25024, '<td valign="top">Great portrait, great focus and DOF, stands out well from the darker background, a minor point bur I might like a bit more space on the left for him to look into.</td>', 'Great portrait, great focus and DOF, stands out well from the darker background, a minor point bur I might like a bit more space on the left for him to look into.', '2014-11-10 17:42:54.000000', NULL, 1),
(7283401, 1133795, 150277, '<td valign="top">Wow. Every ugly detail captured. Weird. Great shot.</td>', 'Wow. Every ugly detail captured. Weird. Great shot.', '2014-11-10 17:42:55.000000', NULL, 1),
(7283402, 1133364, 25024, '<td valign="top">This is one of those rare occasions where the eyes should not be in sharp focus, it works really well like this it makes him look well spooky but I''m sure he''s a great and well loved companion.</td>', 'This is one of those rare occasions where the eyes should not be in sharp focus, it works really well like this it makes him look well spooky but I''m sure he''s a great and well loved companion.', '2014-11-10 17:44:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7283403, 1134829, 25024, '<td valign="top">You''ve caught the stern expression well, the rainy or snowy weather adds especially those drops on his wing feathers, a high score.</td>', 'You''ve caught the stern expression well, the rainy or snowy weather adds especially those drops on his wing feathers, a high score.', '2014-11-10 17:46:43.000000', NULL, 1),
(7283404, 1133733, 25024, '<td valign="top">Whilst I hate the idea of captive animals you''ve done a great job of this portrait. My emotions would always get the better of me if I saw an animal like this, I know I just couldn''t take it but you have and you''ve done it well.</td>', 'Whilst I hate the idea of captive animals you''ve done a great job of this portrait. My emotions would always get the better of me if I saw an animal like this, I know I just couldn''t take it but you have and you''ve done it well.', '2014-11-10 17:52:05.000000', NULL, 1),
(7283405, 1133275, 63218, '<td valign="top">oh nicely done!</td>', 'oh nicely done!', '2014-11-10 17:59:30.000000', NULL, 1),
(7283407, 1134936, 25024, '<td valign="top">I''m so intrigued by this image and unable to answer my many questions about it and your title doesn''t help me either! But, I like the creativity and the way it leaves me questioning, thanks.</td>', 'I''m so intrigued by this image and unable to answer my many questions about it and your title doesn''t help me either! But, I like the creativity and the way it leaves me questioning, thanks.', '2014-11-10 18:09:27.000000', NULL, 1),
