(7283411, 1134032, 25024, '<td valign="top">Very well executed, should do well</td>', 'Very well executed, should do well', '2014-11-10 18:17:39.000000', NULL, 1),
(7283412, 1134893, 25024, '<td valign="top">Good lighting, very acrobatic, but I find myself very distracted by the unnatural bulge in his shorts!</td>', 'Good lighting, very acrobatic, but I find myself very distracted by the unnatural bulge in his shorts!', '2014-11-10 18:22:08.000000', NULL, 1),
(7283413, 1134718, 25024, '<td valign="top">I love the detail on the bark of the main trunks and the subtle hues throughout but those few red leaves being red, the more I look at it the more they dominate, I would prefer to see them removed or subdued</td>', 'I love the detail on the bark of the main trunks and the subtle hues throughout but those few red leaves being red, the more I look at it the more they dominate, I would prefer to see them removed or subdued', '2014-11-10 18:28:32.000000', NULL, 1),
(7283416, 1133158, 135629, '<td valign="top">This will probably be an extremely stunning print on a Metallic Pearl paper. It''s almost in the over-processed category, but not quite, hopefully it would print well in large format. The heavy saturation works here, love the definition in the clouds.</td>', 'This will probably be an extremely stunning print on a Metallic Pearl paper. It''s almost in the over-processed category, but not quite, hopefully it would print well in large format. The heavy saturation works here, love the definition in the clouds.', '2014-11-10 18:55:25.000000', NULL, 1),
