INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7283989, 1134614, 30364, '<td valign="top">Nice portrait.  Striking lines and angles give it a lovely geometric dimension.  But the focus (not yours, his) in the young hunter''s eyes is the best part of many good parts.  Also the sand on his skin and hair; suggests he''s been down stalking something.  Something unlucky judging by his evident commitment to the shot.  I think it''s Kalahari somewhere?  That and the quality of the photography says you could well be Harvey.  Harvey or not, thank you.</td>', 'Nice portrait.  Striking lines and angles give it a lovely geometric dimension.  But the focus (not yours, his) in the young hunter''s eyes is the best part of many good parts.  Also the sand on his skin and hair; suggests he''s been down stalking something.  Something unlucky judging by his evident commitment to the shot.  I think it''s Kalahari somewhere?  That and the quality of the photography says you could well be Harvey.  Harvey or not, thank you.', '2014-11-11 11:07:07.000000', NULL, 1),
(7283990, 1134549, 25024, '<td valign="top">I think I would heed that warning! Good sharp focus where it matters</td>', 'I think I would heed that warning! Good sharp focus where it matters', '2014-11-11 11:07:46.000000', NULL, 1),
(7283991, 1133524, 25024, '<td valign="top">A lovely image, I like everything about it, good luck</td>', 'A lovely image, I like everything about it, good luck', '2014-11-11 11:09:03.000000', NULL, 1),
(7283992, 1133709, 25024, '<td valign="top">Through the clock? A good cityscape but I feel the softness at the top and bottom detracts a little, good luck</td>', 'Through the clock? A good cityscape but I feel the softness at the top and bottom detracts a little, good luck', '2014-11-11 11:11:14.000000', NULL, 1),
(7283993, 1134380, 25024, '<td valign="top">Unusual presentation it brings out the see head detail well, good luck</td>', 'Unusual presentation it brings out the see head detail well, good luck', '2014-11-11 11:12:23.000000', NULL, 1),
(7283994, 1134578, 25024, '<td valign="top">Nicely vibrant and natural looking portrait - effervescent! Good lighting, good luck</td>', 'Nicely vibrant and natural looking portrait - effervescent! Good lighting, good luck', '2014-11-11 11:14:14.000000', NULL, 1),
(7283995, 1134211, 25024, '<td valign="top">A great low light landscape enhanced by the distant sunset, should do well</td>', 'A great low light landscape enhanced by the distant sunset, should do well', '2014-11-11 11:15:56.000000', NULL, 1),
(7283996, 1133373, 25024, '<td valign="top">Great capture. The two reds are very dominant and work well together against the green hues of that stormy sea, I just feel the sky lets it down a little, I think there''s still some scope left in the sky. Good luck</td>', 'Great capture. The two reds are very dominant and work well together against the green hues of that stormy sea, I just feel the sky lets it down a little, I think there''s still some scope left in the sky. Good luck', '2014-11-11 11:18:35.000000', NULL, 1),
