(7284003, 1134416, 25024, '<td valign="top">An image which leaves me with lots of questions, which is good, very intriguing, good luck</td>', 'An image which leaves me with lots of questions, which is good, very intriguing, good luck', '2014-11-11 11:25:25.000000', NULL, 1),
(7284004, 1133216, 25024, '<td valign="top">Well controlled night scene, good luck</td>', 'Well controlled night scene, good luck', '2014-11-11 11:27:40.000000', NULL, 1),
(7284007, 1133529, 25024, '<td valign="top">I love the lighting, composition and green of her dress against those lovely subdued tones of the rest of the image, it works really well. With a title such as you have chosen, however, I would expect her to be in a very different position to this, she looks more like she has chosen to sleep there. A very high score, you should do well with this</td>', 'I love the lighting, composition and green of her dress against those lovely subdued tones of the rest of the image, it works really well. With a title such as you have chosen, however, I would expect her to be in a very different position to this, she looks more like she has chosen to sleep there. A very high score, you should do well with this', '2014-11-11 11:33:19.000000', NULL, 1),
(7284009, 1134843, 25024, '<td valign="top">The foreground contrasts work really well here, i like the silhouetted figures too. For me, there is a strong argument for a panoramic crop at the lower cloud level. Good luck</td>', 'The foreground contrasts work really well here, i like the silhouetted figures too. For me, there is a strong argument for a panoramic crop at the lower cloud level. Good luck', '2014-11-11 11:35:18.000000', NULL, 1),
