INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7284546, 1133962, 98339, '<td valign="top">Beautiful picture Rich!!!  Well done!</td>', 'Beautiful picture Rich!!!  Well done!', '2014-11-12 00:44:38.000000', NULL, 0),
